function updateManualForm(){const type=(document.getElementById('manualType')||{}).value||'Person';const label=document.getElementById('manualTitleLabel');if(label)label.textContent=editorTypeConfig(type).title;const fields=document.getElementById('manualSpecificFields');if(fields)fields.innerHTML=manualSpecificFields(type)}
function updateEditFormFields(){const type=(document.getElementById('editType')||{}).value||'Person';const r=S.editingRecord||{};const label=document.getElementById('editTitleLabel');if(label)label.textContent=editorTypeConfig(type).title;const fields=document.getElementById('editSpecificFields');if(fields)fields.innerHTML=editSpecificFields(type,r)}
function ensurePlainTextRecordDialog(){if(document.getElementById('plainTextRecordDialog'))return;document.body.insertAdjacentHTML('beforeend','<dialog id="plainTextRecordDialog"><form id="plainTextRecordForm"><div class="modalHead"><h2>Add record from plain text</h2><p class="muted">Paste unstructured business information. Constrava will infer specific CRM record types and place every proposal in Review &amp; Publish.</p></div><div class="modalBody"><label for="plainTextRecordInput">Plain text</label><textarea id="plainTextRecordInput" name="rawText" required placeholder="Example: Sarah from Bluebird Dental wants a website quote, budget $6,000, follow up tomorrow."></textarea><p class="status" id="plainTextRecordStatus" aria-live="polite"></p></div><div class="modalFoot"><button class="secondary" type="button" id="cancelPlainTextRecord">Cancel</button><button class="primary" type="submit" id="submitPlainTextRecord">Create records for review</button></div></form></dialog>');const dialog=document.getElementById('plainTextRecordDialog'),form=document.getElementById('plainTextRecordForm'),cancel=document.getElementById('cancelPlainTextRecord');if(cancel)cancel.onclick=function(){dialog.close()};form.onsubmit=async function(event){event.preventDefault();const button=document.getElementById('submitPlainTextRecord'),status=document.getElementById('plainTextRecordStatus'),rawText=String(new FormData(form).get('rawText')||'').trim();if(!rawText)return;if(button){button.disabled=true;button.textContent='Creating records...'}if(status)status.textContent='Constrava AI is organizing this text into draft CRM records.';try{await api('/api/records/plan',{method:'POST',body:JSON.stringify({rawText:rawText,kind:'manual_note',sourceId:'source_manual'})});dialog.close();await load();S.crmView='ai-records';render()}catch(error){if(button){button.disabled=false;button.textContent='Create records for review'}if(status)status.textContent=error.message||'Could not create CRM records from this text.'}}}
function openPlainTextRecordDialog(){ensurePlainTextRecordDialog();const dialog=document.getElementById('plainTextRecordDialog'),form=document.getElementById('plainTextRecordForm'),status=document.getElementById('plainTextRecordStatus'),button=document.getElementById('submitPlainTextRecord');if(form)form.reset();if(status)status.textContent='';if(button){button.disabled=false;button.textContent='Create records for review'}dialog.showModal();document.getElementById('plainTextRecordInput').focus()}
function settingsContent(){const s=S.settings||{};const selected=function(name,value){return String(s[name]||'')===value?' selected':''};const checked=s.notifications===false?'':' checked';return '<div class="grid two"><section class="card"><div class="in"><h2>Workspace settings</h2><p class="muted">These settings are saved to your signed-in account and restored when you log back in.</p><form id="workspaceSettingsForm"><label>Workspace name</label><input name="workspaceName" value="'+esc(s.workspaceName||WORKSPACE_LABEL||'Personal workspace')+'"><label>Theme</label><select name="theme"><option value="white-blue"'+selected('theme','white-blue')+'>White and dark blue</option><option value="green-white"'+selected('theme','green-white')+'>Green and white</option><option value="compact-dark"'+selected('theme','compact-dark')+'>Compact dark</option></select><label>Layout density</label><select name="density"><option value="comfortable"'+selected('density','comfortable')+'>Comfortable</option><option value="compact"'+selected('density','compact')+'>Compact</option></select><label>Default CRM section</label><select name="defaultCrmView"><option value="overview"'+selected('defaultCrmView','overview')+'>Overview</option><option value="all"'+selected('defaultCrmView','all')+'>All Records</option><option value="Person"'+selected('defaultCrmView','Person')+'>Contacts</option><option value="Company"'+selected('defaultCrmView','Company')+'>Companies</option><option value="Deal"'+selected('defaultCrmView','Deal')+'>Deals</option><option value="Task"'+selected('defaultCrmView','Task')+'>Tasks</option><option value="Note"'+selected('defaultCrmView','Note')+'>Notes</option><option value="edit"'+selected('defaultCrmView','edit')+'>Edit Records</option></select><label style="display:flex;gap:8px;align-items:center;margin-top:10px"><input type="checkbox" name="notifications" value="true"'+checked+'> Save notification preference</label><br><button class="primary">Save settings</button><p class="status" id="settingsStatus"></p></form></div></section><section class="card"><div class="in"><h2>Account storage</h2><p class="muted">Records, plans, reports, analytics events, and settings are separated by your account workspace.</p><div class="item"><b>Workspace ID</b><p class="muted">'+esc(s.workspaceId||'Assigned when signed in')+'</p></div><div class="item"><b>Last saved</b><p class="muted">'+esc(s.updatedAt?s.updatedAt.slice(0,19).replace('T',' '):'Not saved yet')+'</p></div></div></section></div>'}
function crmCount(type){if(type==='all')return S.records.length;if(type==='ai-records')return (S.aiRecords||[]).length;if(type==='overview'||type==='edit')return '';return S.records.filter(function(r){return r.type===type}).length}
function crmShell(content){const items=[['overview','Overview'],['ai-records','Review &amp; Publish'],['all','All Records'],['Person','Contacts'],['Company','Companies'],['Deal','Deals'],['Task','Tasks'],['Note','Notes'],['edit','Edit Records']],summary=(S.summary&&S.summary.metrics)||{};return '<div class="crmPage"><section class="crmHero"><div class="crmHeroGlow crmHeroGlowOne"></div><div class="crmHeroGlow crmHeroGlowTwo"></div><div class="crmHeroContent"><div class="crmHeroCopy"><div class="crmHeroActions"><button class="crmHeroAction crmHeroActionPrimary" type="button" id="crmPlainTextRecord">Add record from plain text</button><button class="crmHeroAction crmHeroActionSecondary" type="button" id="crmPriorityCheck">AI Priority Check</button><button class="crmHeroAction crmHeroActionPrimary" type="button" id="crmEditRecords">Edit Records</button></div><span class="crmEyebrow"><i></i>Customer intelligence</span><h2>Relationships, moving forward.</h2><p>Keep every contact, company, opportunity, and next action connected in one vivid workspace.</p></div><div class="crmHeroStats"><span><b>'+S.records.length+'</b><small>Total records</small></span><span><b>'+crmCount('Deal')+'</b><small>Active deals</small></span><span><b>'+money(summary.revenueOpportunity)+'</b><small>Opportunity</small></span></div></div></section><div class="crmShell"><aside class="crmSide"><div class="crmSideTitle">CRM sections</div><p class="muted crmSideIntro"><b>Review &amp; Publish</b> is where you edit and approve AI-created drafts before they enter the CRM.</p>'+items.map(function(item){const id=item[0],label=item[1];return '<button class="crmTab '+(S.crmView===id?'active':'')+'" data-crm="'+id+'"><span>'+label+'</span><span>'+crmCount(id)+'</span></button>'}).join('')+'</aside><div class="crmCanvas">'+content+'</div></div></div>'}
function recordRow(r){return '<div class="item recordCard"><div><span class="pill">'+esc(r.type)+'</span> <b>'+esc(r.title)+'</b><div class="fieldLine">ID: '+esc(r.id)+' · Added: '+esc((r.createdAt||'').slice(0,10))+' · Edited: '+esc((r.updatedAt||'').slice(0,10))+'</div><div class="fieldLine">'+esc(recordFields(r)||((r.tags||[]).join(' · ')))+'</div><div class="fieldLine">'+esc((r.priorityReasons||[])[0]||'')+'</div></div><div style="display:grid;gap:8px;justify-items:end"><span class="pill">'+Math.round(r.priorityScore||0)+'</span><button class="secondary" data-edit-record="'+esc(r.id)+'">Edit</button></div></div>'}
function ensureEditDialog(){if(document.getElementById('editRecordDialog'))return;document.body.insertAdjacentHTML('beforeend','<dialog id="editRecordDialog"><form id="editRecordForm"><div class="modalHead"><h2 id="editRecordHeading">Edit record</h2><p class="muted" id="editRecordIdLabel"></p></div><div class="modalBody"><input type="hidden" name="id" id="editRecordId"><label>Type of record</label><select name="type" id="editType"><option value="Person">Person</option><option value="Company">Company</option><option value="Deal">Deal</option><option value="Task">Task</option><option value="Note">Note</option></select><label id="editTitleLabel">Title</label><input name="title" id="editTitle" required><label>Priority</label><select name="priorityLevel" id="editPriority"><option value="low">Low</option><option value="normal">Normal</option><option value="high">High</option><option value="highest">Highest - show in notifications</option></select><label>Associated date</label><input name="associatedDate" id="editAssociatedDate" type="date"><label>Description</label><textarea name="description" id="editDescription"></textarea><label>Tags</label><input name="tags" id="editTags" placeholder="Optional, comma separated"><div id="editSpecificFields"></div><p class="status" id="editStatus"></p></div><div class="modalFoot"><button class="secondary" type="button" id="cancelEditRecord">Cancel</button><button class="primary">Save changes</button></div></form></dialog>');document.getElementById('cancelEditRecord').onclick=function(){editRecordDialog.close()};document.getElementById('editType').onchange=updateEditFormFields;document.getElementById('editRecordForm').onsubmit=async function(e){e.preventDefault();const status=document.getElementById('editStatus');if(status)status.textContent='Saving changes...';try{let payload=Object.fromEntries(new FormData(e.target)),endpoint=S.editingRecordIsDraft?'/api/records/drafts/update':'/api/records/update';await api(endpoint,{method:'POST',body:JSON.stringify(payload)});editRecordDialog.close();await load();render()}catch(err){if(status)status.textContent=err.message||'Could not save changes.'}}}
function openRecordEditor(recordId){ensureEditDialog();const draft=(S.aiRecords||[]).find(function(row){return row.id===recordId}),r=draft||S.records.find(function(row){return row.id===recordId});if(!r)return;S.editingRecord=r;S.editingRecordIsDraft=Boolean(draft);const f=r.fields||{};document.getElementById('editRecordHeading').textContent=draft?'Edit AI record':'Edit record';document.getElementById('editRecordId').value=r.id;document.getElementById('editRecordIdLabel').textContent=(draft?'Draft ID: ':'Record ID: ')+r.id;document.getElementById('editType').value=r.type;document.getElementById('editTitle').value=r.title||'';document.getElementById('editPriority').value=priorityLevelForRecord(r);document.getElementById('editAssociatedDate').value=(f.associatedDate||f.dueDate||'').slice(0,10);document.getElementById('editDescription').value=f.description||f.body||f.rawText||'';document.getElementById('editTags').value=(r.tags||[]).join(', ');updateEditFormFields();editRecordDialog.showModal()}
function editRecordsContent(){return crmShell('<div class="grid two"><section class="card"><div class="in"><h2>Edit Records</h2><p class="muted">Create a manual record with the required type and title. Constrava generates the record ID, date added, and edit history automatically.</p><form id="manualRecordForm"><label>Type of record</label><select name="type" id="manualType"><option value="Person">Person</option><option value="Company">Company</option><option value="Deal">Deal</option><option value="Task">Task</option><option value="Note">Note</option></select><label id="manualTitleLabel">Name</label><input name="title" required placeholder="Required"><label>Priority</label><select name="priorityLevel"><option value="low">Low</option><option value="normal" selected>Normal</option><option value="high">High</option><option value="highest">Highest - show in notifications</option></select><label>Associated date</label><input name="associatedDate" type="date"><label>Description</label><textarea name="description" placeholder="Optional notes or saved text for this record"></textarea><label>Tags</label><input name="tags" placeholder="Optional, comma separated"><div id="manualSpecificFields"></div><br><button class="primary">Create manual record</button><p class="status" id="manualStatus"></p></form></div></section><section class="card"><div class="in"><h2>AI Add</h2><p class="muted">Paste a lead, note, email, or form submission. Constrava will infer the best CRM record types and draft them for review.</p><form id="aiForm"><textarea name="rawText" required placeholder="Example: Sarah from Bluebird Dental wants a website quote, budget $6,000, follow up tomorrow."></textarea><br><br><button class="primary">Create AI plan</button></form></div></section></div><div style="margin-top:16px">'+list('Recently edited records',S.records.slice(0,6),'No records yet')+'</div>')}
